demo_5x5 = [
    [0, 0, 2, 0, 0],
    [0, 2, 0, 2, 0],
    [2, 0, 0, 0, 2],
    [0, 1, 0, 0, 0],
    [0, 0, 1, 0, 0]
]

# Find all filled positions with their values
filled = {}
for r in range(5):
    for c in range(5):
        if demo_5x5[r][c] != 0:
            filled[(r,c)] = demo_5x5[r][c]

print("Filled positions:")
for (r,c), v in sorted(filled.items()):
    print(f"  ({r},{c}): {v}")

# Now compute actual Manhattan distance from center (2,2)
print("\nDistances from center:")
for (r,c), v in sorted(filled.items()):
    dist = abs(r - 2) + abs(c - 2)
    print(f"  ({r},{c}): dist={dist}, value={v}")

# Kathine check: all filled positions have distance = 1 OR distance = 2
distances = set()
for (r,c) in filled:
    distances.add(abs(r - 2) + abs(c - 2))
print(f"\nAll distances present: {distances}")

